PRAGMA foreign_keys=OFF;
BEGIN;
CREATE TABLE IF NOT EXISTS subject(id TEXT PRIMARY KEY, name TEXT, accent TEXT, status TEXT);
CREATE TABLE IF NOT EXISTS zone(id TEXT PRIMARY KEY, subject_id TEXT, ord INTEGER, name TEXT, topic TEXT, min_level INTEGER);
CREATE TABLE IF NOT EXISTS item(id INTEGER PRIMARY KEY AUTOINCREMENT, zone_id TEXT, q TEXT, expr TEXT, opts_json TEXT, a INTEGER, hint TEXT, difficulty TEXT, knowledge TEXT);
CREATE TABLE IF NOT EXISTS zone_pokemon(zone_id TEXT, dex INTEGER, name TEXT, type TEXT, rarity TEXT);
CREATE TABLE IF NOT EXISTS content_version(id INTEGER PRIMARY KEY AUTOINCREMENT, subject_id TEXT, built_at TEXT, agent TEXT, source_notes TEXT, status TEXT);
