INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Urutan langkah untuk membuat sandwich adalah: 1. Ambil roti 2. Oleskan selai 3. Letakkan isi di roti. Pernyataan mana yang paling benar tentang urutan ini?','step 1 → step 2 → step 3','["Langkah 1 dan 2 bisa ditukar","Semua langkah harus berurutan","Urutan langkah tidak penting selama semua dikerjakan"]',1,'Dalam sequence, urutan langkah sering kali sangat penting agar hasilnya benar.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','What is the next number in this pattern: 2, 4, 6, 8, __?','2 → 4 → 6 → 8 → ?','["9","10","11","12"]',1,'Look at how much each number increases from the previous one.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Pola ini naik 3 setiap kali: 5, 8, 11, 14, __. Angka berikutnya adalah?','5 (+3) 8 (+3) 11 (+3) 14 (+3) ?','["16","17","18","19"]',1,'Selisih antara setiap angka adalah sama. Hitung dari 14 ditambah selisih tersebut.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','What does the AND logic gate do? It outputs ''true'' when...','AND gate: input1, input2 → output','["either input is true","both inputs are true","at least one input is false"]',1,'AND means you need BOTH conditions to be satisfied, like ''do chores AND finish homework''.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Gerbang OR menghasilkan ''true'' ketika...','OR gate: input1, input2 → output','["salah satu input true atau kedua-duanya true","kedua input harus true","kedua input harus false"]',0,'OR lebih mudah: cukup SATU saja yang true, hasilnya sudah true.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','What does the NOT logic gate do?','NOT: input → output','["It turns true to false and false to true","It keeps the input the same","It adds a second input"]',0,'NOT is like saying ''the opposite'': if something is true, NOT makes it false.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Jika Rini ingin main game HANYA jika sudah selesai PR dan sudah tidur siang, gerbang logic apa yang dipakai?','condition: PR selesai AND tidur siang = boleh main','["OR gate","AND gate","NOT gate"]',1,'Kedua syarat harus terpenuhi. Itu adalah AND (semua harus benar).','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','You can eat dessert if Mom says yes OR Dad says yes. Which logic gate is this?','dessert if (Mom=yes) OR (Dad=yes)','["AND gate","OR gate","NOT gate"]',1,'If either parent says yes, you can eat dessert. That''s OR logic.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Pola warna: merah, biru, merah, biru, merah, biru. Warna ke-7 adalah?','red, blue, red, blue, red, blue, ?','["merah","biru","hijau","kuning"]',0,'Polanya berulang setiap 2 warna. Hitung posisi ke-7 dalam pola berulang.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Sequence ini: 1, 1, 2, 3, 5, 8, __. Angka berikutnya?','Fibonacci: 1, 1, 2, 3, 5, 8, ?','["10","11","13","15"]',2,'Setiap angka adalah jumlah dari dua angka sebelumnya. 5 + 8 = ?','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Which statement is true? (Use AND logic)','(2 > 1) AND (3 < 5) = ?','["true","false"]',0,'Check each part: ''2 > 1'' is true, and ''3 < 5'' is true. With AND, both true = true.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Apakah statement ini true atau false? (4 < 2) OR (5 = 5)','(4 < 2) OR (5 = 5) = ?','["true","false"]',0,'''4 < 2'' itu salah (false), tapi ''5 = 5'' itu benar (true). OR cukup butuh satu yang true.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Aku punya rule: IF cuaca panas THEN minum air. Hari ini cuaca panas. Apa yang harus dilakukan?','IF (cuaca = panas) THEN (minum air)','["minum air","tidak minum air","tunggu perintah lagi"]',0,'IF kondisinya terpenuhi (cuaca panas = benar), maka THEN aksinya harus dikerjakan.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','What comes next in the sequence? A, B, C, A, B, C, A, B, C, __?','A, B, C, A, B, C, A, B, C, ?','["A","B","C","D"]',0,'This repeating pattern cycles every 3 letters. Count where position 10 falls in the cycle.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Langkah algoritma: 1. Buka pintu 2. Masuk rumah 3. Tutup pintu. Jika langkah 2 dan 3 ditukar, apa akibatnya?','sequence: 1 → 2 → 3 vs. 1 → 3 → 2','["Hasilnya sama saja","Kamu tidak bisa masuk, karena pintu sudah tertutup terlebih dahulu","Tidak ada perbedaan"]',1,'Bayangkan: kalau tutup pintu dulu sebelum masuk, kamu masih ada di luar — bagaimana kamu bisa masuk?','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','If you are 10 years old AND you have finished homework, you can play video games. Your status: age 10 (true), homework (true). Can you play?','IF (age >= 10) AND (homework_done) THEN play_games','["Yes","No"]',0,'Both conditions are true. With AND, both must be true for the result to be yes.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','Pola ini: ◆ ◇ ◆ ◇ ◆ ◇ __. Simbol ke-7 adalah?','◆ ◇ ◆ ◇ ◆ ◇ ?','["◇","◆","□","○"]',1,'Polanya berganti-ganti setiap satu. Posisi ganjil adalah ◆, posisi genap adalah ◇.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_1','It is raining is TRUE. What does NOT(it is raining) equal?','NOT(true) = ?','["true","false"]',1,'NOT flips the value. If the input is true, the output is the opposite.','easy','');
