INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','Apa itu loop dalam programming?','','["Cara komputer mengulangi perintah berkali-kali","Jenis kabel internet","Program yang rusak","Alat untuk membuat lingkaran"]',0,'Loop membantu kita tidak perlu menulis kode yang sama berulang kali.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','If you want a robot to move forward 5 steps, which approach uses a loop?','repeat 5 times { move() }','["move() move() move() move() move()","repeat 5 times: move()","print(''move'')","if forward then stop"]',1,'A loop lets you do the same thing multiple times with less code.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','Variable dalam programming paling mirip dengan apa?','points = 10','["Kotak penyimpanan untuk menyimpan angka atau teks","Password internet","Komponen fisik komputer","Jenis jaringan"]',0,'Bayangkan seperti kotak yang bisa menyimpan nilai, dan nilai itu bisa berubah.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','A network connects devices together. What is the MAIN purpose of a network?','','["To make devices slower","To allow devices to share information and communicate","To store files only","To create passwords"]',1,'Think about why your home WiFi connects your phone and computer.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','Untuk mencari rute terpendek dari titik A ke titik B di sebuah jaringan, kita perlu apa?','','["Menebak secara acak","Algorithm (cara berpikir sistematis)","Menghapus semua rute","Menambah lebih banyak titik"]',1,'Algorithm adalah langkah-langkah logis untuk menyelesaikan masalah.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','Berikut ini cara kerja loop yang paling efisien untuk menghitung angka 1 hingga 100:','for i = 1 to 100 { print(i) }','["Menulis angka 1, 2, 3, ... 100 secara manual","Menggunakan loop: for i = 1 to 100","Menghapus program dan mulai lagi","Tidak bisa dihitung"]',1,'Loop memungkinkan komputer melakukan pekerjaan repetitif secara otomatis.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','What happens if a loop condition is NEVER met?','while true { print(''hello'') }','["The loop stops immediately","The loop runs forever (infinite loop)","The program deletes itself","Nothing happens"]',1,'If the condition to stop the loop is never reached, the loop keeps repeating endlessly.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','Jika variable score = 5, dan kita jalankan loop ''repeat 3 times: score = score + 1'', berapa nilai score pada akhirnya?','score = 5
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','In a network, a ''connection'' atau ''link'' is like what?','','["A broken wire","A road between two cities","A password","A mistake in code"]',1,'Think of data traveling from one device to another along this path.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','Pernyataan mana yang BENAR tentang internet?','','["Internet adalah satu komputer besar","Internet adalah jaringan global yang menghubungkan miliaran device","Internet hanya bisa diakses di sekolah","Internet tidak butuh infrastruktur fisik sama sekali"]',1,'Internet menghubungkan komputer, ponsel, dan perangkat lain di seluruh dunia.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','A loop with a counter works like what?','for counter = 1 to 5 { print(counter) }','["A random number generator","Counting: 1, 2, 3... until you reach a goal","A password system","A way to delete files"]',1,'The counter starts at 1 and goes up until it meets the stop condition.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','Dalam sebuah game, untuk membuat karakter berjalan melingkar 4 kali, kita gunakan apa?','repeat 4 times { walk() }','["4 perintah walk() terpisah","if statement","repeat 4 times: walk()","variable score"]',2,'Repeat adalah cara singkat untuk mengatakan ''lakukan ini berkali-kali''.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','What is TRUE about variables in a loop?','total = 0
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','Sebuah jaringan komputer membutuhkan berapa device MINIMUM untuk disebut ''network''?','','["1 device","2 device yang saling terhubung","10 device","100 device"]',1,'Untuk berkomunikasi, minimal ada 2 pihak yang terhubung.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','When you send an email, data travels through a network. What is the BEST description of this process?','','["Your email appears instantly everywhere at once","Your email travels from device to device along network connections until it reaches the recipient","Your email is stored inside the WiFi router permanently","Email does not use networks"]',1,'Data harus melewati beberapa tahap untuk sampai ke penerima.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','Debugging sebuah loop berarti apa?','','["Menghapus loop dari program","Mencari dan memperbaiki kesalahan dalam logika loop","Menambah lebih banyak variable","Membuat loop berjalan lebih cepat"]',1,'Debug berarti mencari bug (kesalahan) dan memperbaikinya.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','In the context of networks, what does ''path from A to B'' mean?','','["The physical road between two cities","The route that data takes from one device to another through network connections","A variable in a program","A type of loop"]',1,'Think of it as the journey data makes to reach its destination.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_2','AI like a chatbot learns by repeating a process thousands of times. Which programming concept makes this kind of repetition possible?','repeat many_times { adjust_AI_values() }','["A single variable","A loop that keeps running until the AI improves enough","A network cable","A password"]',1,'Repetition is key — the AI adjusts a little bit each time through the loop.','medium','');
