INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Urutan langkah (steps) yang benar untuk membuat sandwich: (1) ambil roti, (2) olesi mayones, (3) letakkan selada, (4) tutup dengan roti kedua. Manakah urutan algorithm yang BENAR?','(1) → (2) → (3) → (4)','["(1) → (2) → (3) → (4)","(3) → (1) → (2) → (4)","(2) → (1) → (4) → (3)","(4) → (1) → (2) → (3)"]',0,'Pikirkan urutan logis (logical order): mulai dari alas, tambah isinya, tutup.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','You want to find a number in a list using binary search. The first step is to check the middle element. What should you do NEXT if the middle element is too small?','middle < target','["Search the right half of the list","Search the left half of the list","Start over from the beginning","Stop, the number is not there"]',0,'Jika middle terlalu kecil, target pasti di sebelah kanan.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Program untuk login memiliki steps: (1) minta email, (2) minta password, (3) cek password benar?, (4) buka halaman utama. Tetapi pengguna tidak bisa login padahal password benar. Step mana yang HILANG?','(1) (2) (3) (4)','["Step untuk cek email terdaftar di database","Step untuk reset password","Step untuk kirim notifikasi","Step untuk pilih bahasa"]',0,'Sebelum cek password, apakah email sudah ada di sistem?','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','What does this code do? if (age >= 13) { print(''Boleh main'') } else { print(''Terlalu muda'') }','if...else conditional','["Cek apakah umur minimum 13, jika ya boleh main, jika tidak tampilkan pesan terlalu muda","Selalu tampilkan ''Boleh main'' untuk semua umur","Cek apakah umur tepat 13 tahun saja","Tidak ada aksi yang jelas"]',0,'Tanda >= berarti ''lebih besar dari atau sama dengan'' (greater than or equal to).','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Algorithm mencari buah terbaik di pasar: (1) lihat buah pertama, (2) bandingkan kualitasnya dengan pilihan terbaik saat ini (current best), (3) jika lebih baik, ganti pilihan, (4) pindah ke buah berikutnya, (5) ulangi sampai selesai. Ini adalah contoh algorithm apa?','repeat...until/loop','["Loop dengan kondisi pengulangan","Conditional if/else saja","Sorting algorithm","Binary search algorithm"]',0,'Ada kata ''ulangi'' dan ''sampai selesai'' — itu ciri khas loop.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','You''re sorting a list of numbers: 5, 2, 8, 1, 9. First you compare 5 and 2, then swap them to get: 2, 5, 8, 1, 9. What should you do NEXT?','[2, 5, 8, 1, 9]','["Compare 5 and 8, then decide if swap is needed","Go back and compare 2 and 5 again","Stop, the list is sorted","Compare 1 and 9 first"]',0,'Bubble sort membandingkan elemen yang berdekatan (adjacent elements) dari kiri ke kanan.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Program game: ''Kalau poin > 100, dapat hadiah. Kalau poin antara 50-100, dapat badge. Kalau poin < 50, game over.'' Ini menggunakan apa?','poin > 100 OR (50 <= poin <= 100)','["Multiple if/else conditionals","Loop repeat","Binary search algorithm","Linear search algorithm"]',0,'Ada beberapa kondisi berbeda yang dicek satu per satu — itu multiple if/else.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','A program prints numbers 1 to 5, but the output is only: 1, 2, 3, 4 (number 5 is missing). Code: for (i = 1; i < 5; i++) { print(i) }. What is the bug?','for (i = 1; i < 5; i++)','["Kondisi i < 5 harus diganti i <= 5 supaya angka 5 ikut tercetak (off-by-one error)","Kondisi i = 1 harus diganti i = 0","Loop harus dihapus dan diganti if/else","Tidak ada bug, output sudah benar"]',0,'Cek kapan loop berhenti: i < 5 berhenti SEBELUM i=5. Gunakan <= agar 5 ikut.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Which step is MISSING from this algorithm to find the tallest person in a classroom? (1) Lihat person pertama, catat tingginya. (2) Lihat person berikutnya, bandingkan tingginya. (3) Kalau lebih tinggi, catat person baru. (4) Ulangi untuk semua person.','max_height = first_person; for each person...','["Step untuk output/tampilkan person tertinggi di akhir","Step untuk reset tinggi ke 0","Step untuk sort dari terendah ke tertinggi","Step untuk hitung rata-rata tinggi"]',0,'Algorithm cari maksimum harus memberitahu siapa hasilnya di akhir.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Program cek nomor ganjil atau genap: if (nomor % 2 == 0) { print(''genap'') } else { print(''ganjil'') }. Berapa angka yang BENAR kategorinya?','nomor % 2 == 0','["4 → genap, 7 → ganjil","4 → ganjil, 7 → genap","Keduanya selalu ganjil","Keduanya selalu genap"]',0,'Modulo operator (%) memberikan sisa bagi. Sisa 0 = genap, sisa 1 = ganjil.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Urutan steps mengisi form online: (1) scroll ke bawah, (2) isi nama, (3) isi email, (4) centang checkbox ''saya setuju syarat'', (5) klik submit. Di posisi mana seharusnya checkbox ''saya setuju'' ada?','(1) → (2) → (3) → (4) → (5)','["Sebelum klik submit, jadi posisi (4) sudah benar","Setelah klik submit","Di paling atas, sebelum isi nama","Tidak ada checkbox, langsung submit"]',0,'UX yang baik: syarat & ketentuan (terms) biasanya disetujui SEBELUM submit.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','This debugging challenge: script for a teacher to grade students stops working after grading 25 students, even though there are 50 total. What is the MOST LIKELY cause?','loop 0..50; if grade_count == 25 break;','["Ada break statement yang keluar dari loop di tengah jalan (bug)","Compiler error, program tidak bisa jalan sama sekali","Tidak ada loop, hanya if/else","Grade hanya bisa sampai 25 maksimal"]',0,'Jika 25 siswa berhasil tapi siswa ke-26 tidak, mungkin ada condition yang terminate loop lebih awal.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Algorithm game ''tebak angka'': (1) generate angka random 1-100, (2) minta pemain input tebakan, (3) cek apakah sama, (4) kalau tidak, kasih petunjuk ''terlalu besar'' atau ''terlalu kecil'', (5) ulangi sampai benar. Kondisi KAPAN loop berhenti?','while tebakan != angka_rahasia','["Ketika pemain berhasil menebak angka yang benar (tebakan == angka)","Setelah 5 tebakan","Ketika pemain ketik angka paling besar (100)","Program tidak bisa berhenti, harus manual close"]',0,'Loop berlanjut WHILE (selama) kondisi benar. Berhenti WHEN (ketika) tebakan benar.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Kode filter konten untuk anak-anak: if (rating == ''G'' OR rating == ''PG'') { tampilkan } else { blokir }. Rating mana yang TIDAK akan ditampilkan?','OR condition','["Rating ''PG-13'' dan ''R'' tidak ditampilkan","Rating ''G'' dan ''PG'' tidak ditampilkan","Semua rating ditampilkan","Hanya rating ''R'' yang diblokir, ''PG-13'' tetap tampil"]',0,'OR menerima minimal satu kondisi benar. Hanya ''G'' dan ''PG'' yang lolos, lainnya masuk else → blokir.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Debugging challenge: app chat ada bug — message dari teman A selalu hilang ketika teman B kirim message. Urutan mana yang salah? (1) simpan message di database, (2) tampilkan message baru di layar, (3) check apakah message baru ada, (4) delete message lama.','(1) → (3) → (2) → (4)','["Langkah (4) DELETE dijalankan SEBELUM (2) TAMPILKAN — message hilang sebelum sempat ditampilkan!","Langkah (1) SIMPAN harus setelah (2) TAMPILKAN","Langkah (3) CHECK tidak perlu","Urutan sudah benar, bug ada di database"]',0,'Jangan delete sebelum ditampilkan! Urutan benar: simpan → cek → tampilkan → baru hapus.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','A game checks if a player can open a door. Code: if (hasKey AND atDoor) { openDoor() }. Bug report: a player with a key, standing at the door, but health = 0 (already dead) can still open the door. What is the fix?','if (hasKey AND atDoor AND health > 0)','["Tambahkan kondisi AND health > 0 ke dalam if statement","Ganti AND jadi OR supaya lebih fleksibel","Hapus kondisi atDoor karena tidak perlu","Tidak ada bug, logika sudah benar"]',0,'Bug muncul karena satu kondisi penting (health > 0) belum ada di if statement.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','Algorithm validasi password: (1) check panjang >= 8 karakter AND (2) ada huruf besar AND (3) ada angka. Mana password yang LOLOS validasi?','AND condition: 8char AND uppercase AND digit','["''MyPass123'' — 9 huruf, ada ''M'' besar, ada ''123''","''mypassword'' — 10 huruf tapi tanpa angka","''Pas1'' — ada huruf besar dan angka tapi cuma 4 huruf","''PASSWORD'' — 8 huruf dan ada besar tapi tanpa angka"]',0,'AND berarti SEMUA kondisi harus true. Cek satu per satu: panjang? uppercase? angka?','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_3','You''re debugging a loop that counts down from 10 to 1. Code: for (i = 10; i > 0; i = i - 1) { print(i) }. This is CORRECT. But if you change i > 0 to i >= 0, what happens?','for loop condition','["Loop akan print sampai 0 (11 kali total: 10, 9, 8 ... 1, 0) bukan 10 kali","Loop tidak akan jalan sama sekali","Loop akan infinite (tidak pernah berhenti)","Loop tetap sama, print 10-1 seperti biasa"]',0,'Ganti > 0 jadi >= 0 menambah satu iterasi (i=0 juga ikut diprint).','medium','');
