INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Apa itu Internet?','','["Jaringan komputer besar yang menghubungkan jutaan perangkat di seluruh dunia","Sebuah website yang hanya bisa diakses dari rumah","Aplikasi yang hanya ada di ponsel","Mesin pencari yang mencari informasi"]',0,'Internet adalah jaringan global yang menghubungkan komputer, ponsel, dan perangkat lain.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','What is a website?','','["A collection of web pages connected by links and displayed in a browser","A type of email account","A password used to protect your computer","A software that blocks bad websites"]',0,'A website is made of multiple pages that you visit using a browser.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','URL adalah singkatan dari apa?','','["Uniform Resource Locator — alamat website di internet","User Resource Language — bahasa untuk menulis website","Ultra Resource Link — tautan yang sangat cepat","Universal Robot Launcher — peluncur robot otomatis"]',0,'URL adalah alamat lengkap yang kamu ketik di browser untuk mengunjungi website.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Apa fungsi utama browser?','','["Menampilkan website dan halaman web dari internet","Mengunci semua data pribadi di komputer","Membuat password yang aman","Mengirim email ke orang lain"]',0,'Browser adalah program yang kamu gunakan untuk mengakses dan melihat website.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','What is a search engine?','','["A tool that finds websites and information based on your keywords","A type of email service","A program that creates new websites","A security system that protects passwords"]',0,'A search engine like Google helps you find information on the internet by searching for keywords.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Apa itu email?','','["Surat elektronik yang dapat dikirim melalui internet dengan cepat","Nama panggilan untuk website","Jenis password yang sangat kuat","Program untuk membuat file dokumen"]',0,'Email memungkinkan kamu mengirim pesan ke orang lain melalui internet.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Apa yang membuat password menjadi kuat dan aman?','','["Panjang minimal 8 karakter, campuran huruf besar, huruf kecil, angka, dan simbol","Menggunakan nama panggilan atau tanggal lahir untuk mudah diingat","Menggunakan hanya satu jenis karakter (hanya huruf atau hanya angka)","Membagikan password kepada teman agar mereka bisa membantu"]',0,'Password yang aman menggabungkan berbagai jenis karakter dan tidak mudah ditebak.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Why should you NEVER share your personal data online?','','["Because strangers can use it to harm you, steal your identity, or commit fraud","Because personal data takes up too much storage space","Because it will slow down your internet connection","Because websites don''t have space to store your information"]',0,'Personal data like your address, phone number, and birthday must be kept private to protect your safety.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Apa yang harus kamu lakukan jika menerima pesan dari orang asing di internet?','','["Jangan membalas, jangan klik link, dan beri tahu orang tua atau guru","Langsung klik link untuk melihat apa yang mereka inginkan","Bagikan informasi pribadi agar mereka percaya kepada kamu","Abaikan saja tanpa memberi tahu siapa pun"]',0,'Orang asing online bisa berniat tidak baik, jadi kamu harus hati-hati dan meminta bantuan orang dewasa.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','What does a ''suspicious link'' usually look like?','','["A URL that is very long, contains strange characters, or asks you to login again","Any link that appears in a search result","A link in an email from your friend","A link that is short and easy to remember"]',0,'Suspicious links often try to trick you into giving passwords or personal information.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Mana pernyataan yang BENAR tentang keamanan online?','','["Jangan pernah membuka attachment (file) dari email orang yang tidak kamu kenal","Semua email dari alamat yang terlihat resmi pasti aman untuk dibuka","Attachment dari teman selalu aman tanpa perlu dicek siapa pengirimnya","Virus hanya ada di website yang terlihat ''jelek''"]',0,'Email attachment dari orang tidak dikenal bisa berisi virus atau malware yang membahayakan komputer kamu.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Is it safe to use the same password for all your online accounts?','','["No, because if one account is hacked, all your accounts become unsafe","Yes, because it is easier to remember","Yes, because hackers only target one account at a time","No password is ever hacked, so it does not matter"]',0,'Using the same password everywhere puts all your accounts at risk.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Apa kepanjangan dari ''HTTP'' dan ''HTTPS''?','','["HTTP adalah protokol standar; HTTPS adalah versi terenkripsi yang lebih aman","Keduanya adalah nama browser yang berbeda","HTTP adalah untuk menerima email; HTTPS adalah untuk mengirim","Keduanya adalah singkatan untuk password"]',0,'HTTPS lebih aman karena enkripsi; cari ikon gembok di browser untuk memastikan website aman.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','What is ''phishing'' in online safety?','','["A scam where criminals pretend to be trustworthy to steal your login info or personal data","A real fishing game you can play online","A way to make your password stronger","A feature in browsers that blocks ads"]',0,'Phishing uses fake emails or websites that look real to trick you into giving away your information.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Kapan waktu yang tepat untuk memberi tahu orang tua atau guru tentang masalah online?','','["Segera, tanpa menunggu, jika kamu melihat konten aneh, tidak nyaman, atau ada yang mengajak bertemu","Hanya ketika kamu sudah merasa sangat takut atau kesal","Tidak perlu diberitahu jika masalahnya kecil","Hanya jika teman-teman kamu juga mengalami hal yang sama"]',0,'Orang tua dan guru adalah partner keselamatan online kamu yang harus segera tahu tentang masalah apapun.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','What should you do if someone online asks you to meet them in person?','','["NEVER agree; tell a trusted adult immediately","Only agree if they seem nice and friendly","Meet them in a public place to be safe","Ask them for more personal information first to check if they are real"]',0,'Online strangers can hide who they really are, so never meet them in person without a trusted adult.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_4','Mengapa penting untuk menggunakan privacy settings di media sosial dan aplikasi?','','["Untuk mengontrol siapa yang bisa melihat data dan postingan kamu, mencegah akses orang asing","Karena aplikasi yang tidak memiliki privacy settings akan crash","Untuk membuat profil kamu lebih populer","Tidak ada alasan, privacy settings tidak berguna"]',0,'Privacy settings membantu melindungi data pribadi kamu dari orang yang tidak perlu mengetahuinya.','medium','');
INSERT INTO zone(id,subject_id,ord,name,topic,min_level) VALUES('compsci_5','compsci',5,'Otak Buatan','kecerdasan_buatan',21) ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id,ord=excluded.ord,name=excluded.name,topic=excluded.topic,min_level=excluded.min_level;
