INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Apa itu kecerdasan buatan (Artificial Intelligence)?','','["Sebuah robot fisik yang bisa bergerak","Program komputer yang dapat belajar dan membuat keputusan seperti manusia","Sebuah permainan video yang sangat canggih","Sebuah mesin untuk menghasilkan listrik"]',1,'AI adalah program, bukan robot fisik, dan bisa belajar dari data.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Which of these is an example of AI you use every day?','','["A pencil sharpener","Voice assistant like Siri or Google Assistant","A bicycle","A paper notebook"]',1,'Think about programs that listen to you and answer questions.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Ketika kamu mendengarkan musik di aplikasi streaming, lagu yang disarankan datang dari mana?','','["Dipilih secara acak oleh komputer","AI mempelajari lagu yang kamu suka dan menyarankan lagu serupa","Diputuskan oleh pemilik aplikasi setiap hari","Dari daftar lagu paling populer saja"]',1,'AI belajar dari kebiasaan dengarmu dan mencoba menemukan yang sesuai.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','What does it mean that ''AI learns from data''?','','["AI reads textbooks like humans do","AI looks at many examples and finds patterns to improve its decisions","AI copies all information from the internet","AI automatically becomes smarter without any examples"]',1,'Learning from data means looking at patterns in many examples.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Maps application (seperti Google Maps) menggunakan AI untuk apa?','','["Hanya menampilkan nama-nama jalan","Belajar dari data lalu lintas untuk menyarankan rute tercepat","Membaca pikiran pengemudi","Mengubah cuaca di kota"]',1,'AI menganalisis data kendaraan yang melewati jalan untuk prediksi kemacetan.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Mengapa kita tidak boleh percaya 100% pada AI?','','["Karena AI selalu berbohong","Karena AI bisa membuat kesalahan dan tidak mengerti konteks seperti manusia","Karena AI tidak punya tenaga listrik","Karena AI tidak bisa berhitung"]',1,'Ingat: AI belajar dari data, jadi kalau data salah, AI bisa keliru.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','When you use a chatbot to answer homework questions, what should you do?','','["Trust everything it says without checking","Verify the answer by checking other sources or asking a teacher","Use it only if you are very tired","Never use chatbot for learning"]',1,'Always double-check information from any source, including AI.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Chatbot adalah contoh AI yang melakukan apa?','','["Menghapus semua email kamu","Mengobrol dan menjawab pertanyaan berdasarkan teks yang dikirim pengguna","Menutup akun media sosial","Menghapus file dari komputer"]',1,'Chatbot adalah program yang berdiskusi dengan manusia.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Bagaimana AI bisa mengenal wajah di foto?','','["Dengan membaca teks di sampingnya","Dengan belajar dari ribuan contoh foto wajah sampai bisa mengenali pola ciri wajah","Dengan menanya ke Internet siapa yang ada di foto","Dengan mengenal suara orang di ruangan"]',1,'AI belajar dari banyak contoh untuk mengenali pola dan ciri khas.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','What is a mistake that AI can make?','','["Forgetting to turn on the monitor","Misclassifying objects because it learned from limited or biased examples","Breaking the keyboard","Deleting the internet"]',1,'AI makes mistakes because of incomplete or wrong training data.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Ketika menggunakan AI untuk membuat pekerjaan, apa yang harus kamu lakukan agar jujur?','','["Katakan saja itu hasil kerjamu sendiri tanpa mention AI","Jelaskan bahwa kamu menggunakan AI dan kemudian mengedit hasilnya sendiri","Jangan pernah gunakan AI","Copy-paste hasil AI tanpa dikerjakan ulang"]',1,'Kejujuran berarti memberi tahu orang lain kalau kamu pakai AI.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Aplikasi yang menyarankan video untuk ditonton adalah contoh dari:','','["Internet hacking","AI recommendation system yang mempelajari preferensi viewer","Website biasa tanpa AI","Iklan acak"]',1,'Platform seperti YouTube gunakan AI untuk lihat apa yang sering kamu tonton.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Why should you be careful about sharing personal information with a chatbot?','','["Because chatbots are made of metal","Because chatbots might remember your information and you don''t fully know who uses it","Because chatbots will steal your toys","Because chatbots cannot understand text"]',1,'Your data could be stored and used—so don''t share private info like passwords or home address.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','AI belajar dari data. Kalau data yang diberikan tidak bagus, apa yang terjadi?','','["AI akan menjadi lebih pintar otomatis","AI akan membuat keputusan yang buruk atau bias","AI akan berhenti bekerja selamanya","Tidak ada yang terjadi"]',1,'Masukan buruk = hasil buruk. Ini disebut garbage in, garbage out.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Which is a way to use AI wisely and honestly?','','["Use AI to completely copy homework answers","Use AI as a tool to help you understand and learn, then add your own ideas","Never think about what AI produced","Pretend AI suggestions are 100% correct"]',1,'Wise use means AI helps you learn, not replaces your thinking.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Apa bedanya antara Artificial Intelligence dan manusia dalam belajar?','','["Tidak ada perbedaan sama sekali","AI belajar dari pola dalam data; manusia belajar juga dari pola tapi dengan pemahaman konteks yang lebih dalam","Hanya manusia yang bisa belajar","AI bisa belajar tanpa data apapun"]',1,'Keduanya belajar, tapi manusia punya pemahaman yang lebih dalam.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Search engines like Google use AI to do what?','','["Count how many websites exist","Understand what you''re searching for and rank the most relevant pages for you","Block all advertisements forever","Translate your search into alien language"]',1,'AI learns from trillions of searches to understand what answer you really want.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('compsci_5','Jika AI membuat keputusan yang merugikan seseorang (misalnya AI menolak aplikasi pinjaman dengan tidak adil), siapa yang bertanggung jawab?','','["Hanya AI yang bertanggung jawab","Manusia yang membuat AI dan orang/perusahaan yang menggunakan AI harus bertanggung jawab","Tidak ada yang bertanggung jawab","Hanya si pemohon yang salah"]',1,'AI adalah alat yang dibuat dan digunakan manusia—manusia memiliki tanggung jawab akhir.','hard','');
